function validate([n, edges, values]) {
  if (!Number.isInteger(n) || n < 2 || n > 50000) return 'n is between 2 and 5 * 10^4.';
  if (!Array.isArray(edges) || edges.length !== n - 1) return 'edges needs exactly n - 1 pairs.';
  if (!Array.isArray(values) || values.length !== n) return 'values needs exactly n numbers.';
  if (values.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Every value is between 1 and 10^9.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = (x) => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const e of edges) {
    if (!Array.isArray(e) || e.length !== 2 || e.some(v => !Number.isInteger(v) || v < 0 || v >= n)) return 'Each edge joins two nodes between 0 and n - 1.';
    const a = find(e[0]), b = find(e[1]);
    if (a === b) return 'The edges must form a tree (no cycles or repeated edges).';
    root[a] = b;
  }
  return null;
}

