function maxXor(n, edges, values) {
  const graph = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) {
    graph[a].push(b);
    graph[b].push(a);
  }
  const sum = new Array(n).fill(0);
  const fillSums = (node, parent) => {
    sum[node] = values[node];
    for (const child of graph[node]) {
      if (child !== parent) {
        sum[node] += fillSums(child, node);
      }
    }
    return sum[node];
  };
  fillSums(0, -1);

  const BITS = 46;
  const trie = [[0, 0]];
  const bitAt = (x, b) => Math.floor(x / 2 ** b) % 2;
  const insert = (x) => {
    let cur = 0;
    for (let b = BITS - 1; b >= 0; b--) {
      const bit = bitAt(x, b);
      if (trie[cur][bit] === 0) {
        trie[cur][bit] = trie.length;
        trie.push([0, 0]);
      }
      cur = trie[cur][bit];
    }
  };
  const query = (x) => {
    let cur = 0;
    let result = 0;
    for (let b = BITS - 1; b >= 0; b--) {
      const want = 1 - bitAt(x, b);
      if (trie[cur][want] !== 0) {
        result += 2 ** b;
        cur = trie[cur][want];
      } else {
        cur = trie[cur][1 - want];
      }
    }
    return result;
  };
  let best = 0;
  const visit = (node, parent) => {
    if (trie.length > 1) {
      best = Math.max(best, query(sum[node]));
    }
    for (const child of graph[node]) {
      if (child !== parent) {
        visit(child, node);
      }
    }
    insert(sum[node]);
  };
  visit(0, -1);
  return best;
}

