function maxXor(n, edges, values) {
  // Root the tree with a BFS, then for every node collect its descendants by climbing parent links.
  const adj = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }
  const parent = new Array(n).fill(-1);
  const order = [0];
  const seen = new Array(n).fill(false);
  seen[0] = true;
  for (let h = 0; h < order.length; h++) for (const v of adj[order[h]]) if (!seen[v]) { seen[v] = true; parent[v] = order[h]; order.push(v); }
  const isAncestor = (a, b) => { for (let x = b; x !== -1; x = parent[x]) if (x === a) return true; return false; };
  const total = [];
  for (let u = 0; u < n; u++) {
    let s = 0n;
    for (let v = 0; v < n; v++) if (isAncestor(u, v)) s += BigInt(values[v]);
    total.push(s);
  }
  let best = 0n;
  for (let u = 0; u < n; u++) for (let v = u + 1; v < n; v++) {
    if (isAncestor(u, v) || isAncestor(v, u)) continue;
    const x = total[u] ^ total[v];
    if (x > best) best = x;
  }
  return Number(best);
}

