function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1900 + Math.floor(rand() * 101) : 2 + Math.floor(rand() * 9);
  const shape = rand();
  // Random relabelling keeps node 0 as the root but scatters the other labels.
  const label = [0];
  const rest = Array.from({ length: n - 1 }, (_, i) => i + 1);
  for (let i = rest.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [rest[i], rest[j]] = [rest[j], rest[i]]; }
  label.push(...rest);
  const edges = [];
  for (let i = 1; i < n; i++) {
    // Shapes: chain, star, broom-like (recent parents), or uniformly random parents.
    let p;
    if (shape < 0.15) p = i - 1;
    else if (shape < 0.3) p = 0;
    else if (shape < 0.55) p = Math.max(0, i - 1 - Math.floor(rand() * 3));
    else p = Math.floor(rand() * i);
    edges.push(rand() < 0.5 ? [label[p], label[i]] : [label[i], label[p]]);
  }
  for (let i = edges.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  const mode = rand();
  const value = () => mode < 0.3 && !large ? 1 + Math.floor(rand() * 8) : mode < 0.6 ? 1000000000 - Math.floor(rand() * 1000) : 1 + Math.floor(rand() * 1000000000);
  const values = Array.from({ length: n }, value);
  return [n, edges, values];
}
